using UnityEngine;
using UnityEngine.Rendering;
using TMPro;
namespace LWS.TruckSports {
// Presentation adapter over existing Cinemachine rally cameras and Taxi cab/look.
// It never enables/disables competitors or writes their simulation state.
[DefaultExecutionOrder(300)]
public sealed class SportsDrivingViews:MonoBehaviour {
 public SportsEventSession session;public SportsRallyViews rally;public Transform[] cabs;public SportsCabLook[] looks;public TMP_Text modeLabel;
 public bool independentViewModes,localElevated;public int defaultMode;public Transform[] cabMounts;readonly int[] participantModes=new int[4];public int ViewMode(int view)=>independentViewModes&&view>=0&&view<rally.Humans&&rally.owners[view]>=0&&rally.owners[view]<participantModes.Length?participantModes[rally.owners[view]]:Mode;
 public int Mode{get;private set;}public string Preference=>session.GetType().Name+".DrivingView.v1";
 readonly Quaternion[] headings=new Quaternion[4];Renderer[][] exterior;Renderer[] hidden;bool[] prior;Camera hiddenFor;int lastMode=-1;bool lastAI;
 void Awake(){Mode=Mathf.Clamp(SportsPrefs.GetInt(Preference,defaultMode),0,2);for(int i=0;i<4;i++)participantModes[i]=Mathf.Clamp(SportsPrefs.GetInt(Preference+".Player"+i,localElevated?Mode:Mathf.Max(1,Mode)),localElevated?0:1,2);exterior=new Renderer[rally.trucks.Length][];int max=0;for(int i=0;i<exterior.Length;i++){exterior[i]=rally.trucks[i].visuals.GetComponentsInChildren<Renderer>(true);max=Mathf.Max(max,exterior[i].Length);}prior=new bool[max];RefreshLabel();}
 void OnEnable(){RenderPipelineManager.beginCameraRendering+=BeginCamera;RenderPipelineManager.endCameraRendering+=EndCamera;}
 void OnDisable(){RenderPipelineManager.beginCameraRendering-=BeginCamera;RenderPipelineManager.endCameraRendering-=EndCamera;Restore();if(looks!=null)foreach(var look in looks)look.ResetLook();}
 public void Cycle(){Select((Mode+1)%3);}
 public void CycleParticipant(int slot){if(!independentViewModes||slot<0||slot>=4){Cycle();return;}if(Mode==0&&!localElevated)Select(1);participantModes[slot]=localElevated?(participantModes[slot]+1)%3:participantModes[slot]==2?1:2;SportsPrefs.SetInt(Preference+".Player"+slot,participantModes[slot]);SportsPrefs.Save();for(int v=0;v<rally.Humans;v++)cabs[v].gameObject.SetActive(ViewMode(v)==2&&rally.views[v].view.enabled);}
 public void Select(int mode){Mode=Mathf.Clamp(mode,0,2);if(independentViewModes&&(Mode>0||localElevated))for(int i=0;i<4;i++){participantModes[i]=Mode;SportsPrefs.SetInt(Preference+".Player"+i,Mode);}SportsPrefs.SetInt(Preference,Mode);SportsPrefs.Save();Layout();RefreshLabel();session.menus.Dirty();}
 public void RefreshLabel(){if(modeLabel!=null){var button=modeLabel.GetComponentInParent<Michsky.UI.Heat.ButtonManager>();if(button!=null){button.buttonText="VIEW: "+new[]{localElevated?"SPLIT ELEVATED":"SHARED ARENA","SPLIT CHASE","SPLIT CAB"}[Mode];button.UpdateUI();}else modeLabel.text="VIEW: "+new[]{localElevated?"SPLIT ELEVATED":"SHARED ARENA","SPLIT CHASE","SPLIT CAB"}[Mode];}}
 public void Layout(){Restore();lastMode=Mode;lastAI=SportsCameraOptions.ShowAI;rally.Restore();int mask=(1<<26)|(1<<27)|(1<<28)|(1<<29);rally.broadcast.view.cullingMask&=~mask;if(Mode==0&&!localElevated){foreach(var camera in rally.views)camera.view.enabled=false;rally.broadcast.view.enabled=true;rally.broadcast.view.rect=new Rect(0,0,1,1);session.cameras=new[]{rally.broadcast.view};}for(int i=0;i<4;i++){headings[i]=Quaternion.identity;looks[i].ResetLook();var camera=rally.views[i].view;camera.orthographic=false;camera.cullingMask=(camera.cullingMask&~mask)|(1<<(26+i));cabs[i].gameObject.SetActive(ViewMode(i)==2&&camera.enabled&&(Mode!=0||localElevated));}if(rally.weather!=null){rally.weather.vendor.AllowCameras.Clear();foreach(var camera in session.cameras)rally.weather.vendor.AllowCameras.Add(camera);}}
 public bool NeedsArena=>Mode==0&&!localElevated||rally.Humans==0;
 public void Tick(float dt){if(lastMode!=Mode||lastAI!=SportsCameraOptions.ShowAI)Layout();if(NeedsArena)return;rally.Follow(dt);for(int v=0;v<rally.Humans;v++){if(rally.retiredViews!=null&&rally.retiredViews.OwnsView(v)){cabs[v].gameObject.SetActive(false);continue;}cabs[v].gameObject.SetActive(ViewMode(v)==2&&rally.views[v].view.enabled);if(ViewMode(v)==0&&localElevated){int owner=rally.owners[v];var heading=Vector3.ProjectOnPlane(rally.trucks[owner].transform.forward,Vector3.up).normalized;if(heading.sqrMagnitude<.5f)heading=Vector3.forward;rally.views[v].Pose(rally.trucks[owner].body.position+heading*8,new Vector3(0,30,0)-heading*38,67);continue;}if(ViewMode(v)!=2)continue;int slot=rally.owners[v];var truck=rally.trucks[slot];var direction=Vector3.ProjectOnPlane(truck.transform.forward,Vector3.up);if(direction.sqrMagnitude>.01f&&Vector3.Dot(truck.transform.up,Vector3.up)>.2f)headings[v]=Quaternion.Slerp(headings[v],Quaternion.LookRotation(direction),1-Mathf.Exp(-dt*9));var camera=rally.views[v].view;camera.transform.position=truck.body.position+headings[v]*(cabMounts!=null&&slot<cabMounts.Length&&cabMounts[slot]!=null?truck.transform.InverseTransformPoint(cabMounts[slot].position):new Vector3(-.17f,1.3f,.65f));camera.transform.rotation=looks[v].Apply(headings[v],session.setup.players[slot],slot,v==0,session.Live,SportsLookOptions.Sensitivity,SportsLookOptions.InvertY);camera.fieldOfView=78;camera.nearClipPlane=.025f;rally.views[v].cabSteering.Bind(truck);}}
 void BeginCamera(ScriptableRenderContext context,Camera camera){if(NeedsArena)return;for(int v=0;v<rally.Humans;v++)if(ViewMode(v)==2&&rally.views[v].view==camera&&(rally.retiredViews==null||!rally.retiredViews.OwnsView(v))){Restore();hidden=exterior[rally.owners[v]];hiddenFor=camera;for(int i=0;i<hidden.Length;i++){prior[i]=hidden[i].forceRenderingOff;hidden[i].forceRenderingOff=true;}break;}}
 void EndCamera(ScriptableRenderContext context,Camera camera){if(camera==hiddenFor)Restore();}
 void Restore(){if(hidden!=null)for(int i=0;i<hidden.Length;i++)if(hidden[i]!=null)hidden[i].forceRenderingOff=prior[i];hidden=null;hiddenFor=null;}
}
}
